<details class="reservation-lessons mt-2" id="reservation-{{ $booking->id }}"><summary>View Lessons</summary>
@php($reservationLessons = $lessons->filter(fn ($entry) => $entry->classroom_id === $booking->classroom_id && $entry->schoolClass?->class_group_id === $booking->class_group_id && $entry->schoolClass?->session === $booking->classSession?->session && $entry->day === $booking->day_of_week && \App\Services\TeacherManagementService::overlaps($entry->starts_at, $entry->ends_at, $booking->starts_at, $booking->ends_at))->sortBy('starts_at'))
@forelse($reservationLessons as $entry)<article class="border rounded p-2 mt-2" data-reservation-lesson-id="{{ $entry->id }}"><strong>{{ substr($entry->starts_at,0,5) }}–{{ substr($entry->ends_at,0,5) }} — {{ $entry->isRelaxation() ? 'Relaxation Period' : $entry->subject?->name }}</strong><span class="d-block">{{ $entry->schoolClass?->label }}</span><small class="d-block">{{ $entry->isRelaxation() ? 'Room reserved · No teacher-led lesson' : ($entry->teacher?->name ?? 'Teacher assignment needs review') }} · Room {{ $classroom->room_number }}</small></article>
@empty<p class="small mt-2">No confirmed lesson records for this reservation. The room remains reserved.</p>@endforelse
</details>
